def solve(inputs: dict) -> float:
    X = inputs['SEED']
    A = inputs['A']
    B = inputs['B']
    M = inputs['M']
    K = inputs['K']

    for _ in range(K):
        X = ((A * X) + B) % M

    return float(X)

